  "inlineSchema": "datasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\nmodel User {\n  id           Int              @id @default(autoincrement())\n  email        String           @unique\n  password     String\n  name         String?\n  baseCurrency String           @default(\"SAR\")\n  createdAt    DateTime         @default(now())\n  receipts     Receipt[]\n  products     Product[]\n  people       Person[]\n  settlements  DebtSettlement[]\n  wallets      Wallet[]\n}\n\nmodel Wallet {\n  id                Int                 @id @default(autoincrement())\n  userId            Int\n  user              User                @relation(fields: [userId], references: [id], onDelete: Cascade)\n  name              String\n  type              String              @default(\"CASH\") // CASH, BANK, VISA, WALLET\n  balance           Float               @default(0) // Stored in Cents (e.g. 1000 = 10.00)\n  color             String              @default(\"#4CC9F0\")\n  createdAt         DateTime            @default(now())\n  receipts          Receipt[]           @relation(\"PrimaryReceipts\")\n  secondaryReceipts Receipt[]           @relation(\"SecondaryReceipts\")\n  settlements       DebtSettlement[]\n  transactions      WalletTransaction[]\n}\n\nmodel Person {\n  id            Int                @id @default(autoincrement())\n  userId        Int\n  user          User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  name          String\n  color         String             @default(\"#4CC9F0\")\n  emoji         String             @default(\"👤\")\n  createdAt     DateTime           @default(now())\n  splits        ReceiptItemSplit[]\n  settlements   DebtSettlement[]\n  payerReceipts Receipt[]          @relation(\"ReceiptPayer\")\n\n  @@unique([userId, name])\n}\n\nmodel Receipt {\n  id                    Int              @id @default(autoincrement())\n  userId                Int\n  user                  User             @relation(fields: [userId], references: [id], onDelete: Cascade)\n  storeName             String\n  date                  DateTime\n  total                 Int // Stored in Cents\n  currency              String\n  tax                   Int              @default(0) // Stored in Cents\n  discount              Int              @default(0) // Stored in Cents\n  imageUrl              String?\n  confidence            Float\n  status                String           @default(\"APPROVED\") // APPROVED, NEEDS_REVIEW\n  payerType             String           @default(\"USER\") // USER, PERSON\n  payerPersonId         Int?\n  payerPerson           Person?          @relation(\"ReceiptPayer\", fields: [payerPersonId], references: [id], onDelete: SetNull)\n  walletId              Int?\n  wallet                Wallet?          @relation(\"PrimaryReceipts\", fields: [walletId], references: [id], onDelete: SetNull)\n  secondaryWalletId     Int?\n  secondaryWalletAmount Int              @default(0) // Stored in Cents\n  secondaryWallet       Wallet?          @relation(\"SecondaryReceipts\", fields: [secondaryWalletId], references: [id], onDelete: SetNull)\n  payerName             String? // Retained for backward compatibility\n  items                 ReceiptItem[]\n  settlements           DebtSettlement[]\n  createdAt             DateTime         @default(now())\n}\n\nmodel Product {\n  id          Int            @id @default(autoincrement())\n  userId      Int\n  user        User           @relation(fields: [userId], references: [id], onDelete: Cascade)\n  name        String // Normalised Arabic name, e.g. \"صدر دجاج\"\n  category    String // e.g. \"طعام ومشروبات\", \"تقنية\"\n  description String?\n  imageUrl    String?\n  aliases     ProductAlias[]\n  items       ReceiptItem[]\n  createdAt   DateTime       @default(now())\n\n  @@unique([userId, name])\n}\n\nmodel ProductAlias {\n  id        Int     @id @default(autoincrement())\n  productId Int\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  alias     String // Original scanned name, e.g. \"Chicken Breast\"\n\n  @@unique([productId, alias])\n}\n\nmodel ReceiptItem {\n  id           Int                @id @default(autoincrement())\n  receiptId    Int\n  receipt      Receipt            @relation(fields: [receiptId], references: [id], onDelete: Cascade)\n  productId    Int\n  product      Product            @relation(fields: [productId], references: [id], onDelete: Cascade)\n  originalName String // The name as it appeared in this specific receipt\n  quantity     Float              @default(1)\n  price        Int // Price per unit in Cents\n  discount     Int                @default(0) // In Cents\n  total        Int // (quantity * price) - discount (In Cents)\n  splitMethod  String             @default(\"NONE\") // NONE, EQUAL, PERCENTAGE, CUSTOM\n  splits       ReceiptItemSplit[]\n}\n\nmodel ReceiptItemSplit {\n  id            Int         @id @default(autoincrement())\n  receiptItemId Int\n  receiptItem   ReceiptItem @relation(fields: [receiptItemId], references: [id], onDelete: Cascade)\n  personId      Int?\n  person        Person?     @relation(fields: [personId], references: [id], onDelete: Cascade)\n  personName    String // Stored name for display even if person is deleted\n  amount        Int // Stored in Cents\n  ratio         Float       @default(0) // Percentage share (e.g. 50.0)\n  isUser        Boolean     @default(false) // true if this split belongs to the main user\n}\n\nmodel DebtSettlement {\n  id        Int      @id @default(autoincrement())\n  userId    Int\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  personId  Int\n  person    Person   @relation(fields: [personId], references: [id], onDelete: Cascade)\n  receiptId Int?\n  receipt   Receipt? @relation(fields: [receiptId], references: [id], onDelete: SetNull)\n  amount    Float // Stored in Cents. Positive = person paid user; Negative = user paid person\n  date      DateTime @default(now())\n  notes     String?\n  walletId  Int?\n  wallet    Wallet?  @relation(fields: [walletId], references: [id], onDelete: SetNull)\n}\n\nmodel ExchangeRate {\n  id        Int      @id @default(autoincrement())\n  from      String\n  to        String\n  rate      Float\n  updatedAt DateTime @default(now()) @updatedAt\n\n  @@unique([from, to])\n}\n\nmodel WalletTransaction {\n  id          Int      @id @default(autoincrement())\n  walletId    Int\n  wallet      Wallet   @relation(fields: [walletId], references: [id], onDelete: Cascade)\n  amount      Float // Stored in Cents. Positive = Deposit/Inflow, Negative = Withdrawal/Outflow\n  date        DateTime @default(now())\n  description String\n  createdAt   DateTime @default(now())\n}\n",
